"""上下文管理 — 决定 Continue（继续）还是 Spawn Fresh（新建）Worker。决策依据：- 上下文重叠度高 → 继续现有 Worker（SendMessage），保留上下文- 上下文无关或已污染 → 新建 Worker（AgentTool），获得干净上下文"""from __future__ import annotationsfrom dataclasses import dataclass, fieldfrom enum import Enumfrom typing import Dict, Optional, Setclass ContextDecision(str, Enum):    CONTINUE = "continue"  # 继续现有 worker    SPAWN_FRESH = "spawn_fresh"  # 启动新 worker@dataclassclass WorkerContext:    """一个 Worker 持有的上下文快照。"""    worker_id: str    files_touched: Set[str] = field(default_factory=set)    topics: Set[str] = field(default_factory=set)    message_count: int = 0    is_stale: bool = False  # 上下文是否已过期 / 被污染    def overlap_ratio(self, target_files: Set[str], target_topics: Set[str]) -> float:        """计算与目标任务的上下文重叠度 (0-1)。"""        file_overlap = len(self.files_touched & target_files) / max(            len(target_files), 1        )        topic_overlap = len(self.topics & target_topics) / max(len(target_topics), 1)        return (file_overlap + topic_overlap) / 2.0class ContextManager:    """管理所有 Worker 的上下文并做续用 / 新建决策。"""    # 阈值：重叠度超过此值则倾向于 Continue    OVERLAP_THRESHOLD = 0.5    # 消息数超过此值则上下文可能过长，倾向于 Spawn Fresh    MAX_MESSAGES_BEFORE_REFRESH = 50    def __init__(self) -> None:        self._contexts: Dict[str, WorkerContext] = {}    # ---- 注册 / 更新 ----    def register_worker(self, worker_id: str) -> WorkerContext:        ctx = WorkerContext(worker_id=worker_id)        self._contexts[worker_id] = ctx        return ctx    def update_worker(        self,        worker_id: str,        files: Optional[Set[str]] = None,        topics: Optional[Set[str]] = None,        messages_delta: int = 0,    ) -> None:        ctx = self._contexts.get(worker_id)        if ctx is None:            return        if files:            ctx.files_touched.update(files)        if topics:            ctx.topics.update(topics)        ctx.message_count += messages_delta    def mark_stale(self, worker_id: str) -> None:        ctx = self._contexts.get(worker_id)        if ctx:            ctx.is_stale = True    def remove_worker(self, worker_id: str) -> None:        self._contexts.pop(worker_id, None)    # ---- 决策 ----    def decide(        self,        target_files: Set[str],        target_topics: Set[str],    ) -> tuple[ContextDecision, Optional[str]]:        """返回 (决策, 可续用的 worker_id 或 None)。"""        best_worker: Optional[str] = None        best_overlap = 0.0        for wid, ctx in self._contexts.items():            if ctx.is_stale:                continue            if ctx.message_count > self.MAX_MESSAGES_BEFORE_REFRESH:                continue            overlap = ctx.overlap_ratio(target_files, target_topics)            if overlap > best_overlap:                best_overlap = overlap                best_worker = wid        if best_worker is not None and best_overlap >= self.OVERLAP_THRESHOLD:            return ContextDecision.CONTINUE, best_worker        return ContextDecision.SPAWN_FRESH, None    # ---- 查询 ----    def get_context(self, worker_id: str) -> Optional[WorkerContext]:        return self._contexts.get(worker_id)    def get_all_contexts(self) -> Dict[str, WorkerContext]:        return dict(self._contexts)